-- Empty photo slots show the Team's own photos, the ones the current public
-- site already shows (issue #371). Cavour's and VES's launch cards and
-- galleries get their photos (files in public/project-photos/), in every
-- stored version of each, written by `revisionSql(cavourSitePhotos)` and
-- `revisionSql(vesSitePhotos)` (lib/project-content/import.ts). A member with
-- no photo of their own gets the one public/team/ holds for them, written by
-- `memberPhotoSql()` (lib/about/member-photos.ts). The tests in
-- lib/project-content/content.test.ts and lib/about/member-photos.test.ts check
-- this file holds exactly that output.
UPDATE "project_versions" SET "content" = jsonb_set(jsonb_set(jsonb_set(jsonb_set("content", '{launches,entries,0,photos}', '[{"src":"/project-photos/cavour/test-launch-liftoff.webp","alt":"Cavour climbing on its smoke trail above the launch field in Bavaria"},{"src":"/project-photos/cavour/test-launch-landed.webp","alt":"Cavour lying intact in a green field at sunset after its first flight"}]'::jsonb, true), '{launches,entries,1,photos}', '[{"src":"/project-photos/cavour/sa-cup-liftoff.webp","alt":"Cavour leaving the rail in a cloud of desert dust at Spaceport America"},{"src":"/project-photos/cavour/sa-cup-pad.webp","alt":"Cavour on launch pad B2 in the New Mexico desert"}]'::jsonb, true), '{launches,entries,2,photos}', '[{"src":"/project-photos/cavour/euroc-2023-liftoff.webp","alt":"Cavour lifting off at Santa Margarida, Portugal"},{"src":"/project-photos/cavour/euroc-2023-to-the-pad.webp","alt":"Team members carrying Cavour past the tents at EuRoC 2023"}]'::jsonb, true), '{gallery,items}', '[{"src":"/project-photos/cavour/sa-cup-team.webp","alt":"The Team holding Cavour up on a pickup truck in the desert","caption":"Spaceport America Cup 2023, New Mexico"},{"src":"/project-photos/cavour/sa-cup-expo.webp","alt":"Cavour and its poster on the Team''s table at the competition expo","caption":"Spaceport America Cup 2023, New Mexico"},{"src":"/project-photos/cavour/sa-cup-flag.webp","alt":"The Team with the Italian flag at the Spaceport America Cup","caption":"Spaceport America Cup 2023, New Mexico"},{"src":"/project-photos/cavour/euroc-2023-team.webp","alt":"The Team seated together in the competition hall","caption":"EuRoC 2023, Portugal"},{"src":"/project-photos/cavour/euroc-2023-tent.webp","alt":"Team members working on Cavour in the Team''s tent","caption":"EuRoC 2023, Portugal"},{"src":"/project-photos/cavour/test-launch-rail.webp","alt":"Cavour leaving the rail at sunset on its first flight","caption":"Test launch 2023, Bavaria"}]'::jsonb, true) WHERE "content"->>'slug' = 'cavour';
--> statement-breakpoint
UPDATE "project_versions" SET "content" = jsonb_set(jsonb_set(jsonb_set("content", '{launches,entries,0,photos}', '[{"src":"/project-photos/ves/euroc-2024-liftoff.webp","alt":"VES Mark I lifting off at Santa Margarida, Portugal"},{"src":"/project-photos/ves/euroc-2024-to-the-pad.webp","alt":"Team members carrying VES Mark I to the pad at EuRoC 2024"}]'::jsonb, true), '{launches,entries,1,photos}', '[{"src":"/project-photos/ves/irec-2025-pad.webp","alt":"Team members readying VES Mark II on the launch rail in Texas"},{"src":"/project-photos/ves/irec-2025-award.webp","alt":"The Team on stage with VES Mark II and the Italian flag at IREC 2025"}]'::jsonb, true), '{gallery,items}', '[{"src":"/project-photos/ves/euroc-2024-team.webp","alt":"The Team on the competition stage with VES Mark I and the Italian flag","caption":"EuRoC 2024, Portugal"},{"src":"/project-photos/ves/euroc-2024-booth.webp","alt":"Team members showing VES Mark I at the Team''s stand","caption":"EuRoC 2024, Portugal"},{"src":"/project-photos/ves/euroc-2024-stand.webp","alt":"The Team at its stand beside VES Mark I","caption":"EuRoC 2024, Portugal"},{"src":"/project-photos/ves/irec-2025-expo.webp","alt":"VES Mark II and its poster at the competition expo","caption":"IREC 2025, Texas"},{"src":"/project-photos/ves/irec-2025-dusk.webp","alt":"Team members riding out at dusk with VES Mark II in a pickup truck","caption":"IREC 2025, Texas"},{"src":"/project-photos/ves/irec-2025-banner.webp","alt":"VES Mark II held up beside the Team''s banner","caption":"IREC 2025, Texas"}]'::jsonb, true) WHERE "content"->>'slug' = 'ves';
