UPDATE "members" SET "picture" = "photo"."src"
FROM "users", (VALUES ('andrea pantano', '/team/andrea-pantano.jpg'), ('andrea manzo', '/team/andrea-manzo.jpg'), ('riccardo savio', '/team/riccardo-savio.jpg'), ('marco dona', '/team/marco-dona.jpg'), ('marco delogu', '/team/marco-delogu.jpg'), ('samuele lombardi', '/team/samuele-lombardi.jpg'), ('fabio zeloni', '/team/fabio-zeloni.jpg'), ('emir topakci', '/team/emir-topakci.jpg'), ('alessandro rabino', '/team/alessandro-rabino.jpg'), ('daniele brero', '/team/daniele-brero.jpg'), ('alessandro giacobetti', '/team/alessandro-giacobetti.jpg'), ('nicola montagner', '/team/nicola-montagner.jpg'), ('michele rossetto', '/team/michele-rossetto.jpg'), ('giorgio montese', '/team/giorgio-montese.jpg'), ('samuele martello', '/team/samuele-martello.jpg'), ('arda bildik', '/team/arda-bildik.jpg'), ('huseyin gulec', '/team/huseyin-gulec.jpg')) AS "photo" ("name", "src")
WHERE "users"."member" = "members"."member_id"
AND "users"."deleted_at" IS NULL
AND lower(btrim(concat_ws(' ', "users"."first_name", "users"."last_name"))) = "photo"."name"
AND (SELECT count(*) FROM "users" AS "same" WHERE "same"."deleted_at" IS NULL AND lower(btrim(concat_ws(' ', "same"."first_name", "same"."last_name"))) = "photo"."name") = 1
AND ("members"."picture" IS NULL OR btrim("members"."picture") = '');
